from cyclopts import App

app = App(name="service")


@app.command
def start():
    """Start the service."""
    print("Service started.")


@app.command
def stop():
    """Stop the service."""
    print("Service stopped.")


@app.default
def status():
    """Show the current service status (runs when no subcommand is given)."""
    print("Service status: unknown")


if __name__ == "__main__":
    app()
